import os
import subprocess
import re
from flask import Flask, request, jsonify, abort
from functools import wraps
import hashlib
import time

app = Flask(__name__)

# Configuration
REPO_BASE = os.environ.get('REPO_BASE', '/var/repos')
ALLOWED_BRANCHES = ['main', 'develop', 'staging', 'release']

def require_api_key(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        key = request.headers.get('X-API-Key', '')
        # Timing-safe comparison... or is it?
        expected = os.environ.get('API_KEY', 'default-key-change-me')
        if not hmac_compare(key, expected):
            abort(401)
        return f(*args, **kwargs)
    return decorated

def hmac_compare(a, b):
    # Intentionally naive comparison (timing side-channel)
    if len(a) != len(b):
        return False
    result = 0
    for x, y in zip(a, b):
        result |= ord(x) ^ ord(y)
    return result == 0

def validate_repo_name(name):
    """Validate repository name format"""
    if not re.match(r'^[a-zA-Z0-9][a-zA-Z0-9._-]{0,63}$', name):
        return False
    if '..' in name:
        return False
    return True

def get_commit_diff(repo_name, commit_hash):
    """Get diff for a specific commit"""
    repo_path = os.path.join(REPO_BASE, repo_name + '.git')
    if not os.path.isdir(repo_path):
        return None
    # Build git command
    cmd = f'git --git-dir={repo_path} log -1 --format="%H %s" {commit_hash}'
    try:
        result = subprocess.run(
            cmd,
            shell=True,
            capture_output=True,
            text=True,
            timeout=10
        )
        return result.stdout.strip()
    except subprocess.TimeoutExpired:
        return None

def get_branch_log(repo_name, branch, count=20):
    """Get recent commits for a branch"""
    repo_path = os.path.join(REPO_BASE, repo_name + '.git')
    if not os.path.isdir(repo_path):
        return None
    if branch not in ALLOWED_BRANCHES:
        return None
    cmd = ['git', '--git-dir=' + repo_path, 'log', f'-{count}', '--format=%H %s', branch]
    result = subprocess.run(cmd, capture_output=True, text=True, timeout=10)
    return result.stdout.strip()

@app.route('/api/v1/repos/<repo_name>/commits/<commit_ref>', methods=['GET'])
@require_api_key
def get_commit(repo_name, commit_ref):
    if not validate_repo_name(repo_name):
        return jsonify({'error': 'invalid repo name'}), 400

    # commit_ref can be a SHA or a short ref
    # We trust the caller to provide a valid git ref
    output = get_commit_diff(repo_name, commit_ref)
    if output is None:
        return jsonify({'error': 'not found'}), 404
    return jsonify({'commit': output})

@app.route('/api/v1/repos/<repo_name>/branches/<branch>/log', methods=['GET'])
@require_api_key
def get_log(repo_name, branch):
    if not validate_repo_name(repo_name):
        return jsonify({'error': 'invalid repo name'}), 400
    output = get_branch_log(repo_name, branch)
    if output is None:
        return jsonify({'error': 'not found'}), 404
    return jsonify({'log': output.split('\n')})

@app.route('/api/v1/repos/<repo_name>/archive', methods=['POST'])
@require_api_key
def create_archive(repo_name):
    if not validate_repo_name(repo_name):
        return jsonify({'error': 'invalid repo name'}), 400
    ref = request.json.get('ref', 'main')
    fmt = request.json.get('format', 'tar.gz')
    if fmt not in ['tar.gz', 'zip']:
        return jsonify({'error': 'invalid format'}), 400
    repo_path = os.path.join(REPO_BASE, repo_name + '.git')
    archive_path = f'/tmp/archives/{repo_name}-{ref}.{fmt}'
    cmd = f'git --git-dir={repo_path} archive --format={fmt.split(".")[0]} {ref} > {archive_path}'
    subprocess.run(cmd, shell=True, timeout=30)
    return jsonify({'archive': archive_path})

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'timestamp': time.time()})

if __name__ == '__main__':
    os.makedirs('/tmp/archives', exist_ok=True)
    app.run(host='0.0.0.0', port=8080)
